## Polars truncates nanosecond datetimes to microsecond when inferring the schema.
```rust
/// Polars will truncate nanoseconds timestamps into microseconds when `try_parse_dates = true`
#[test]
fn test_truncates_nanoseconds() {
    let cursor = std::io::Cursor::new(TEXT);
    let df = CsvReader::new(cursor)
        .has_header(true)
        .with_try_parse_dates(true)
        .finish()
        .unwrap();
    println!("{:?}", df);
    let expected =  DataType::Datetime(TimeUnit::Nanoseconds, Some("UTC".to_string()));
    let received = df.column("start").unwrap().dtype();
    // fails because received is in microseconds
    assert_eq!(&expected, received);
}
