## `strptime` "forgets" about the timezone when using a tz-aware format string
```rust
/// strptime disallows using dt-aware format strings with dt-aware dtypes,
/// but then the resulting column forgets about the dt-awareness
#[test]
fn test_strptime_tz() {
    let cursor = std::io::Cursor::new(TEXT);
    let df = CsvReader::new(cursor)
        .has_header(true)
        .with_try_parse_dates(false)
        .finish()
        .unwrap();

    let strptime_options = polars::prelude::StrptimeOptions {
        // the format string needs the .9f for nanoseconds
        // the %#z makes the format string `tz-aware`, but polars fails to *include* that in the final type
        format: Some("%Y-%m-%dT%H:%M:%S%.9f%#z".to_string()),
        // error out if parsing fails
        strict: true,
        // only parse whole strings
        exact: false,
        // do not build up a cache of nanoseconds timestamps
        cache: false,
    };

    // the timezone on dt_type must be `None` if using a dt_aware formatstring (i.e. the `%#z`)
    let tz = "UTC";
    let dt_type_no_tz = DataType::Datetime(polars::prelude::TimeUnit::Nanoseconds, None);
    let dt_type_with_tz = DataType::Datetime(polars::prelude::TimeUnit::Nanoseconds, Some(tz.to_string()));

    let test1 = df.clone().lazy().with_column(
        col("start")
            .str()
            .strptime(dt_type_no_tz, strptime_options.clone())
            .alias("start_dt")
    ).collect().unwrap();
    println!("{:?}", test1);

    let expected = &dt_type_with_tz;
    let received = df.column("start_dt").unwrap().dtype();
    // fails because received has no timezone
    assert_eq!(expected, received); // comment this out to hit the 2nd assert

    let test2 = df.clone().lazy().with_column(
        col("start")
            .str()
            .strptime(dt_type_with_tz.clone(), strptime_options)
            .alias("start_dt")
    ).collect();
    println!("{:?}", test2);
    // fails because you can not use a tz-aware format with tz-aware type
    // "cannot use strptime with both a tz-aware format and a tz-aware dtype, please drop time zone from the dtype"
    assert!(test2.is_ok());
} 
} 
```

